'use strict';
const H={mean:xs=>xs.reduce((a,b)=>a+b,0)/xs.length};
const p={"weight":1,"rate":0.1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 以示范的观测动作对为监督数据
Object.assign(s, ((s,p)=>({observations:[1,2],actions:[2,4]}))(s, p));
// 计算预测和均方误差
Object.assign(s, ((s,p)=>({predicted:s.observations.map(o=>p.weight*o),errors:s.observations.map((o,i)=>p.weight*o-s.actions[i])}))(s, p));
// 明确损失归约后求导
Object.assign(s, ((s,p)=>({loss:H.mean(s.errors.map(e=>e*e))/2,gradient:H.mean(s.errors.map((e,i)=>e*s.observations[i]))}))(s, p));
// 更新并检查新的观测
Object.assign(s, ((s,p)=>({updatedWeight:p.weight-p.rate*s.gradient,heldOutAction:(p.weight-p.rate*s.gradient)*3}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0)};
const p={"expert":0.5,"draw":0.6};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先保留已有示范
Object.assign(s, ((s,p)=>({dataset:[[1,2]],learnerAction:3,expertAction:4,visitedObservation:2}))(s, p));
// 在当前策略访问状态上请求专家标签
Object.assign(s, ((s,p)=>({label:s.expertAction,executed:p.draw<p.expert?s.expertAction:s.learnerAction}))(s, p));
// 聚合数据再拟合
Object.assign(s, ((s,p)=>({aggregated:s.dataset.concat([[s.visitedObservation,s.label]])}))(s, p));
// 在聚合样本上做闭式线性拟合
Object.assign(s, ((s,p)=>({weight:H.sum(s.aggregated.map(([o,a])=>o*a))/H.sum(s.aggregated.map(([o])=>o*o)),sampleCount:s.aggregated.length}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"gamma":0.9,"lambda":0.9};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把一条终止轨迹的奖励和值对齐
Object.assign(s, ((s,p)=>({rewards:[0,1],values:[.2,.4,0]}))(s, p));
// 先计算两个TD残差
Object.assign(s, ((s,p)=>({deltas:[p.gamma*s.values[1]-s.values[0],1-s.values[1]]}))(s, p));
// 向前累计衰减残差
Object.assign(s, ((s,p)=>({advantages:[s.deltas[0]+p.gamma*p.lambda*s.deltas[1],s.deltas[1]]}))(s, p));
// 构造价值回归目标
Object.assign(s, ((s,p)=>({targets:s.advantages.map((a,i)=>a+s.values[i])}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={clamp:(x,a,b)=>Math.max(a,Math.min(b,x))};
const p={"ratio":1.3,"advantage":1,"clip":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定采样数据与旧策略
Object.assign(s, ((s,p)=>({ratio:p.ratio,advantage:p.advantage}))(s, p));
// 计算未裁剪代理项
Object.assign(s, ((s,p)=>({unclipped:s.ratio*s.advantage}))(s, p));
// 裁剪比值并保留保守项
Object.assign(s, ((s,p)=>({clippedRatio:H.clamp(s.ratio,1-p.clip,1+p.clip),clipped:H.clamp(s.ratio,1-p.clip,1+p.clip)*s.advantage}))(s, p));
// 求单样本PPO目标
Object.assign(s, ((s,p)=>({objective:Math.min(s.unclipped,s.clipped),loss:-Math.min(s.unclipped,s.clipped)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0),
dot:(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0)};
const p={"probability":0.5,"temperature":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 用离散动作切片解释熵正则
Object.assign(s, ((s,p)=>({probabilities:[1-p.probability,p.probability],q:[1,2]}))(s, p));
// 计算期望价值
Object.assign(s, ((s,p)=>({expectedQ:H.dot(s.probabilities,s.q)}))(s, p));
// 计算策略熵
Object.assign(s, ((s,p)=>({entropy:-H.sum(s.probabilities.map(x=>x*Math.log(x)))}))(s, p));
// 合成最大熵目标
Object.assign(s, ((s,p)=>({objective:s.expectedQ+p.temperature*s.entropy}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"bias":0.1,"horizon":3};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 定义真实系统与学习模型
Object.assign(s, ((s,p)=>({initial:0,action:.5}))(s, p));
// 先预测不执行
Object.assign(s, ((s,p)=>({truePath:Array.from({length:p.horizon+1},(_,k)=>k*s.action),modelPath:Array.from({length:p.horizon+1},(_,k)=>k*(s.action+p.bias))}))(s, p));
// 逐步比较预测误差
Object.assign(s, ((s,p)=>({errors:s.modelPath.map((x,i)=>x-s.truePath[i])}))(s, p));
// 分别报告一步与多步质量
Object.assign(s, ((s,p)=>({oneStepError:p.bias,terminalError:s.errors[s.errors.length-1]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"unseenQ":8,"penalty":5};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把离线数据支持范围写出
Object.assign(s, ((s,p)=>({counts:[20,0],q:[2,p.unseenQ]}))(s, p));
// 观察无约束贪心的外推
Object.assign(s, ((s,p)=>({naiveChoice:s.q[0]>=s.q[1]?0:1}))(s, p));
// 用显式支持惩罚作教学对照
Object.assign(s, ((s,p)=>({adjusted:s.q.map((q,i)=>q-(s.counts[i]===0?p.penalty:0))}))(s, p));
// 保留选择与不可识别范围
Object.assign(s, ((s,p)=>({choice:s.adjusted[0]>=s.adjusted[1]?0:1,unseenActionCovered:false}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"achieved":2,"desired":3};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 保存原始目标条件轨迹
Object.assign(s, ((s,p)=>({achieved:p.achieved,desired:p.desired}))(s, p));
// 按原任务计算稀疏奖励
Object.assign(s, ((s,p)=>({originalReward:s.achieved===s.desired?0:-1,originalSuccess:s.achieved===s.desired}))(s, p));
// 生成一个事后目标样本
Object.assign(s, ((s,p)=>({relabeledGoal:s.achieved,relabeledReward:0}))(s, p));
// 把训练增广和评测分开
Object.assign(s, ((s,p)=>({evaluationSuccess:s.originalSuccess,augmentedTrainingPairs:2}))(s, p));
console.log(JSON.stringify(s,null,2));
